<?php
session_start();
require_once __DIR__ . '/../config/auth.php';
require_once __DIR__ . '/../config/database.php';
require_login('../login.php');
if (is_admin()) { header('Location: ../admin/dashboard.php'); exit; }
if (!is_clinic()) { header('Location: ../dashboard/dashboard.php'); exit; }
if (!isset($_SESSION['csrf_token'])) $_SESSION['csrf_token'] = bin2hex(random_bytes(32));

function clinic_h($value): string { return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8'); }
function clinic_sidebar_navigation(array $groups, string $activePage): void {
    $icons = ['overview'=>'fa-gauge-high','requests'=>'fa-droplet','responses'=>'fa-handshake','messages'=>'fa-comments','notifications'=>'fa-bell','profile'=>'fa-hospital','settings'=>'fa-gear'];
    ?>
    <nav aria-label="Clinic navigation">
        <?php foreach ($groups as $groupLabel => $links): ?>
            <div class="clinic-nav-group">
                <p class="clinic-sidebar-section-label"><?= clinic_h($groupLabel) ?></p>
                <?php foreach ($links as $key => $label): ?>
                    <a href="dashboard.php?page=<?= clinic_h($key) ?>" class="<?= $activePage === $key ? 'active' : '' ?>" <?= $activePage === $key ? 'aria-current="page"' : '' ?>><i class="fa-solid <?= clinic_h($icons[$key] ?? 'fa-circle') ?>" aria-hidden="true"></i><span><?= clinic_h($label) ?></span></a>
                <?php endforeach; ?>
                <?php if ($groupLabel === 'Account'): ?><a href="../logout.php"><i class="fa-solid fa-right-from-bracket" aria-hidden="true"></i><span>Logout</span></a><?php endif; ?>
            </div>
        <?php endforeach; ?>
    </nav>
    <?php
}
$pdo = (new Database())->getConnection();
$userId = (int)current_user_id();
$accountStmt = $pdo->prepare("SELECT u.account_status,u.must_change_password,cp.* FROM uinfo u JOIN clinic_profiles cp ON cp.user_id=u.id WHERE u.id=:id AND u.role='clinic' LIMIT 1");
$accountStmt->execute([':id'=>$userId]);
$clinic = $accountStmt->fetch();
if (!$clinic || $clinic['account_status'] !== 'active') { session_destroy(); header('Location: ../login.php?suspended=1'); exit; }
$page = isset($_GET['page']) && is_string($_GET['page']) ? $_GET['page'] : 'overview';
$allowedPages = ['overview','requests','responses','messages','notifications','profile','settings'];
if (!in_array($page,$allowedPages,true)) $page='overview';
$mustChange = (int)$clinic['must_change_password'] === 1;
if ($mustChange && $page !== 'settings') $page='settings';
$flash = $_SESSION['clinic_flash'] ?? null; unset($_SESSION['clinic_flash']);
$csrfToken = $_SESSION['csrf_token'];
$requestStmt = $pdo->prepare("SELECT br.*,(SELECT COUNT(*) FROM request_responses rr WHERE rr.request_id=br.id) AS response_count,(SELECT COUNT(*) FROM request_responses rr WHERE rr.request_id=br.id AND rr.status='pending') AS pending_count FROM blood_requests br WHERE br.requester_id=:id ORDER BY FIELD(br.urgency,'emergency','urgent','routine'),br.needed_by ASC,br.created_at DESC");
$requestStmt->execute([':id'=>$userId]); $requests=$requestStmt->fetchAll();
$statsStmt=$pdo->prepare("SELECT COUNT(*) total,SUM(status='open' AND needed_by>=CURDATE()) active,SUM(status='fulfilled') fulfilled,(SELECT COUNT(*) FROM request_responses rr JOIN blood_requests br2 ON br2.id=rr.request_id WHERE br2.requester_id=:pending_owner AND rr.status='pending') pending FROM blood_requests br WHERE requester_id=:owner");
$statsStmt->execute([':pending_owner'=>$userId,':owner'=>$userId]); $stats=$statsStmt->fetch() ?: [];
$responseStmt=$pdo->prepare("SELECT rr.id response_id,rr.request_id,rr.message,rr.status approval_status,rr.created_at,br.blood_type,br.units,br.hospital,br.location,br.urgency,br.status request_status,br.needed_by,u.fname,u.lname FROM request_responses rr JOIN blood_requests br ON br.id=rr.request_id JOIN uinfo u ON u.id=rr.user_id WHERE br.requester_id=:id ORDER BY FIELD(br.urgency,'emergency','urgent','routine'),rr.created_at DESC");
$responseStmt->execute([':id'=>$userId]); $responses=$responseStmt->fetchAll();
$messageStmt=$pdo->prepare("SELECT rr.id response_id,br.id request_id,br.blood_type,br.hospital,br.urgency,peer.fname,peer.lname,lm.message latest_message,lm.created_at latest_at,(SELECT COUNT(*) FROM request_response_messages unread WHERE unread.response_id=rr.id AND unread.sender_id<>:viewer AND unread.read_at IS NULL) unread_count FROM request_responses rr JOIN blood_requests br ON br.id=rr.request_id JOIN uinfo peer ON peer.id=rr.user_id LEFT JOIN request_response_messages lm ON lm.id=(SELECT MAX(m.id) FROM request_response_messages m WHERE m.response_id=rr.id) WHERE br.requester_id=:owner AND rr.status='accepted' ORDER BY lm.created_at DESC");
$messageStmt->execute([':viewer'=>$userId,':owner'=>$userId]); $conversations=$messageStmt->fetchAll();
$selectedThread=filter_var($_GET['thread'] ?? null,FILTER_VALIDATE_INT) ?: 0; $selectedConversation=null; $messages=[];
foreach($conversations as $conversation) if((int)$conversation['response_id']===$selectedThread){$selectedConversation=$conversation;break;}
if($selectedConversation){$history=$pdo->prepare('SELECT m.*,u.fname,u.lname FROM request_response_messages m JOIN uinfo u ON u.id=m.sender_id WHERE m.response_id=:id ORDER BY m.created_at,m.id');$history->execute([':id'=>$selectedThread]);$messages=$history->fetchAll();$pdo->prepare('UPDATE request_response_messages SET read_at=NOW() WHERE response_id=:id AND sender_id<>:viewer AND read_at IS NULL')->execute([':id'=>$selectedThread,':viewer'=>$userId]);}
$noticeStmt=$pdo->prepare('SELECT n.*,a.fname actor_first,a.lname actor_last FROM member_notifications n LEFT JOIN uinfo a ON a.id=n.actor_id WHERE n.user_id=:id ORDER BY n.created_at DESC LIMIT 100');$noticeStmt->execute([':id'=>$userId]);$notifications=$noticeStmt->fetchAll();
$nav=['overview'=>'Dashboard','requests'=>'Blood Requests','responses'=>'Request Responses','messages'=>'Messages','notifications'=>'Notifications','profile'=>'Facility Profile','settings'=>'Settings'];
$sidebarGroups=['Overview'=>['overview'=>'Dashboard'],'Blood Services'=>['requests'=>'Blood Requests','responses'=>'Request Responses'],'Communication'=>['messages'=>'Messages','notifications'=>'Notifications'],'Facility Management'=>['profile'=>'Facility Profile'],'Account'=>['settings'=>'Settings']];
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= clinic_h($nav[$page]) ?> | BLife PH</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="../assets/user-dashboard.css"><link rel="stylesheet" href="../assets/clinic-dashboard.css"></head>
<body><div class="clinic-shell"><aside class="clinic-sidebar"><a class="clinic-brand" href="dashboard.php"><img src="../images/BlifePH_no_bg.png" alt="BLife PH"><span>BLife PH</span></a><div class="clinic-name"><?= clinic_h($clinic['facility_name']) ?><small><?= clinic_h(ucwords(str_replace('_',' ',$clinic['facility_type']))) ?> · <?php if ((int)$clinic['is_verified'] === 1): ?><b>Verified Institution</b><?php else: ?>Not verified<?php endif; ?></small></div><?php clinic_sidebar_navigation($sidebarGroups, $page); ?></aside>
<main class="clinic-main"><header class="clinic-header"><div><p class="eyebrow">CLINIC / BLOOD BANK PORTAL</p><h1><?= clinic_h($nav[$page]) ?></h1></div><?php if ((int)$clinic['is_verified'] === 1): ?><span class="clinic-verified">Administrator verified</span><?php endif; ?></header>
<?php if($flash): ?><div class="clinic-flash <?= clinic_h($flash['type']) ?>" role="status"><?= clinic_h($flash['message']) ?></div><?php endif; ?>
<?php if($mustChange): ?><p class="clinic-flash" role="status">Change your temporary password before using clinic functions.</p><?php endif; ?>
<?php if($page==='overview' && !$mustChange): ?><section class="clinic-stats"><article><span>Total requests</span><strong><?= (int)($stats['total']??0) ?></strong></article><article><span>Active requests</span><strong><?= (int)($stats['active']??0) ?></strong></article><article><span>Fulfilled</span><strong><?= (int)($stats['fulfilled']??0) ?></strong></article><article><span>Pending responses</span><strong><?= (int)($stats['pending']??0) ?></strong></article></section><section class="clinic-panel"><div class="clinic-section-title"><h2>Recent requests</h2><a href="dashboard.php?page=requests">Manage requests</a></div><?php foreach(array_slice($requests,0,5) as $request): ?><article class="clinic-request"><strong><?= clinic_h($request['blood_type']) ?> · <?= (int)$request['units'] ?> units at <?= clinic_h($request['hospital']) ?></strong><span class="urgency-badge urgency-<?= clinic_h($request['urgency']) ?>"><?= clinic_h(ucfirst($request['urgency'])) ?></span><small><?= clinic_h($request['location']) ?> · needed <?= clinic_h($request['needed_by']) ?> · <?= (int)$request['response_count'] ?> response(s)</small></article><?php endforeach; ?><?php if(!$requests): ?><p>No blood requests yet.</p><?php endif; ?></section>
<?php elseif($page==='requests' && !$mustChange): ?><section class="clinic-panel"><div class="clinic-section-title"><h2>Facility blood requests</h2><button class="clinic-primary" type="button" data-clinic-dialog-open="clinicRequestDialog">Create Blood Request</button></div><dialog class="clinic-dialog" id="clinicRequestDialog"><form method="post" action="action.php" class="clinic-form"><input type="hidden" name="csrf_token" value="<?= clinic_h($csrfToken) ?>"><input type="hidden" name="action" value="clinic_request_create"><header><h2>Create blood request</h2><button type="button" data-clinic-dialog-close>×</button></header><?php clinic_request_fields(); ?><button class="clinic-primary">Publish request</button></form></dialog><?php foreach($requests as $request): ?><article class="clinic-request"><header><strong><?= clinic_h($request['blood_type']) ?> · <?= (int)$request['units'] ?> units</strong><span class="urgency-badge urgency-<?= clinic_h($request['urgency']) ?>"><?= clinic_h(ucfirst($request['urgency'])) ?></span></header><p><strong><?= clinic_h($request['hospital']) ?></strong> · <?= clinic_h($request['location']) ?></p><small>Needed by <?= clinic_h($request['needed_by']) ?> · <?= (int)$request['response_count'] ?> responses · <?= clinic_h(ucfirst($request['status'])) ?></small><p><?= nl2br(clinic_h($request['details'])) ?></p><?php if($request['status']==='open'): ?><details><summary>Edit request</summary><form class="clinic-form" method="post" action="action.php"><input type="hidden" name="csrf_token" value="<?= clinic_h($csrfToken) ?>"><input type="hidden" name="action" value="clinic_request_edit"><input type="hidden" name="request_id" value="<?= (int)$request['id'] ?>"><?php clinic_request_fields($request); ?><button class="clinic-primary">Save changes</button></form></details><form method="post" action="action.php" class="clinic-status-form"><input type="hidden" name="csrf_token" value="<?= clinic_h($csrfToken) ?>"><input type="hidden" name="action" value="clinic_request_status"><input type="hidden" name="request_id" value="<?= (int)$request['id'] ?>"><select name="status"><option value="fulfilled">Fulfilled</option><option value="cancelled">Cancelled</option></select><button class="clinic-secondary">Update status</button></form><?php endif; ?></article><?php endforeach; ?></section>
<?php elseif($page==='responses' && !$mustChange): ?><section class="clinic-panel"><h2>Member responses to your requests</h2><?php foreach($responses as $response): ?><article class="clinic-request"><header><strong><?= clinic_h(trim($response['fname'].' '.$response['lname']) ?: 'BLife PH member') ?></strong><span class="urgency-badge urgency-<?= clinic_h($response['urgency']) ?>"><?= clinic_h(ucfirst($response['urgency'])) ?> request</span></header><p><?= clinic_h($response['blood_type']) ?> · <?= (int)$response['units'] ?> units · <?= clinic_h($response['hospital']) ?> · <?= nl2br(clinic_h($response['message'] ?: 'Offered to help without a message.')) ?></p><?php if($response['approval_status']==='pending' && $response['request_status']==='open'): ?><form method="post" action="../dashboard/action.php"><input type="hidden" name="csrf_token" value="<?= clinic_h($csrfToken) ?>"><input type="hidden" name="action" value="accept_request_response"><input type="hidden" name="response_id" value="<?= (int)$response['response_id'] ?>"><button class="clinic-primary">Accept offer</button></form><?php elseif($response['approval_status']==='accepted'): ?><a href="dashboard.php?page=messages&amp;thread=<?= (int)$response['response_id'] ?>">Open conversation</a><?php else: ?><small>Request is closed.</small><?php endif; ?></article><?php endforeach; ?><?php if(!$responses): ?><p>No responses received yet.</p><?php endif; ?></section>
<?php elseif($page==='messages' && !$mustChange): ?><div class="clinic-messages"><section class="clinic-panel"><h2>Active conversations</h2><?php foreach($conversations as $conversation): ?><a class="clinic-conversation" href="dashboard.php?page=messages&amp;thread=<?= (int)$conversation['response_id'] ?>"><strong><?= clinic_h(trim($conversation['fname'].' '.$conversation['lname']) ?: 'Member') ?></strong><small><?= clinic_h($conversation['hospital']) ?> · <?= clinic_h($conversation['latest_message'] ?: 'Conversation started') ?></small><?php if((int)$conversation['unread_count']): ?><b><?= (int)$conversation['unread_count'] ?></b><?php endif; ?></a><?php endforeach; ?></section><section class="clinic-panel"><?php if($selectedConversation): ?><h2><?= clinic_h(trim($selectedConversation['fname'].' '.$selectedConversation['lname'])) ?></h2><p><?= clinic_h($selectedConversation['hospital']) ?> · <?= clinic_h(ucfirst($selectedConversation['urgency'])) ?> urgency</p><ol class="clinic-history"><?php foreach($messages as $message): ?><li class="<?= (int)$message['sender_id']===$userId?'own':'' ?>"><strong><?= (int)$message['sender_id']===$userId?'Clinic':clinic_h(trim($message['fname'].' '.$message['lname'])) ?></strong><time><?= clinic_h(date('M j, Y g:i a',strtotime($message['created_at']))) ?></time><p><?= nl2br(clinic_h($message['message'])) ?></p></li><?php endforeach; ?></ol><form class="clinic-form" method="post" action="../dashboard/action.php"><input type="hidden" name="csrf_token" value="<?= clinic_h($csrfToken) ?>"><input type="hidden" name="action" value="request_message"><input type="hidden" name="response_id" value="<?= (int)$selectedThread ?>"><input type="hidden" name="return_page" value="messages"><label>Reply<textarea name="message" maxlength="1000" required></textarea></label><button class="clinic-primary">Send message</button></form><?php else: ?><p>Select a conversation.</p><?php endif; ?></section></div>
<?php elseif($page==='notifications' && !$mustChange): ?><section class="clinic-panel"><h2>Notifications</h2><?php foreach($notifications as $notice): ?><article class="clinic-notification"><strong><?= clinic_h(trim(($notice['actor_first']??'').' '.($notice['actor_last']??'')) ?: 'BLife PH') ?></strong> <?= clinic_h($notice['message']) ?><small><?= clinic_h(date('M j, Y g:i a',strtotime($notice['created_at']))) ?></small></article><?php endforeach; ?><?php if(!$notifications): ?><p>No notifications yet.</p><?php endif; ?></section>
<?php elseif($page==='profile' && !$mustChange): ?><section class="clinic-panel"><h2>Administrator-managed identity</h2><dl class="clinic-profile"><dt>Facility</dt><dd><?= clinic_h($clinic['facility_name']) ?></dd><dt>Type</dt><dd><?= clinic_h(ucwords(str_replace('_',' ',$clinic['facility_type']))) ?></dd><dt>Address</dt><dd><?= clinic_h($clinic['facility_address']) ?></dd><dt>City / province</dt><dd><?= clinic_h($clinic['city'].', '.$clinic['province']) ?></dd><dt>Account status</dt><dd><?= clinic_h(ucfirst($clinic['account_status'])) ?></dd></dl><h3>Update contact information</h3><form class="clinic-form" method="post" action="action.php"><input type="hidden" name="csrf_token" value="<?= clinic_h($csrfToken) ?>"><input type="hidden" name="action" value="clinic_profile_update"><label>Contact number<input name="contact_number" maxlength="30" required value="<?= clinic_h($clinic['contact_number']) ?>"></label><label>Official email<input type="email" name="official_email" maxlength="255" required value="<?= clinic_h($clinic['official_email']) ?>"></label><label>Authorized representative<input name="authorized_representative" maxlength="160" required value="<?= clinic_h($clinic['authorized_representative']) ?>"></label><label>Description<textarea name="description" maxlength="1000" rows="4"><?= clinic_h($clinic['description']) ?></textarea></label><button class="clinic-primary">Save contact information</button></form></section>
<?php elseif($page==='settings'): ?><section class="clinic-panel"><h2><?= $mustChange?'Change temporary password':'Account settings' ?></h2><?php if(!$mustChange): ?><p>Change your account password here.</p><?php endif; ?><form class="clinic-form" method="post" action="action.php"><input type="hidden" name="csrf_token" value="<?= clinic_h($csrfToken) ?>"><input type="hidden" name="action" value="clinic_password_change"><label>Current password<input type="password" name="current_password" autocomplete="current-password" required></label><label>New password<input type="password" name="new_password" minlength="12" autocomplete="new-password" required></label><label>Confirm new password<input type="password" name="confirm_password" minlength="12" autocomplete="new-password" required></label><button class="clinic-primary">Update password</button></form></section><?php endif; ?>
</main></div><script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script><script src="../validation/clinic-dashboard.js"></script><?php if($flash): ?><script>if(window.Swal) Swal.fire({icon:<?= json_encode($flash['type']==='error'?'error':'success') ?>,text:<?= json_encode($flash['message']) ?>,timer:2600,showConfirmButton:false});</script><?php endif; ?></body></html>
