function clinic_request_fields(array $request = []): void { ?>
<label>Blood type<select name="blood_type" required><?php foreach(['A+','A-','B+','B-','AB+','AB-','O+','O-'] as $type): ?><option value="<?= clinic_h($type) ?>" <?= ($request['blood_type']??'')===$type?'selected':'' ?>><?= clinic_h($type) ?></option><?php endforeach; ?></select></label><label>Units<input type="number" name="units" min="1" max="20" required value="<?= (int)($request['units']??1) ?>"></label><label>Facility / hospital<input name="hospital" maxlength="160" required value="<?= clinic_h($request['hospital']??'') ?>"></label><label>Location<input name="location" maxlength="160" required value="<?= clinic_h($request['location']??'') ?>"></label><label>Needed by<input type="date" name="needed_by" min="<?= clinic_h(date('Y-m-d')) ?>" required value="<?= clinic_h($request['needed_by']??'') ?>"></label><label>Urgency<select name="urgency" required><?php foreach(['routine'=>'Routine','urgent'=>'Urgent','emergency'=>'Emergency'] as $value=>$label): ?><option value="<?= clinic_h($value) ?>" <?= ($request['urgency']??'routine')===$value?'selected':'' ?>><?= clinic_h($label) ?></option><?php endforeach; ?></select></label><p class="clinic-help">Urgency is self-reported and does not replace medical assessment.</p><label>Additional information<textarea name="details" maxlength="1000" rows="3"><?= clinic_h($request['details']??'') ?></textarea></label>
<?php }
?>
